import React from 'react';

function HeroSection({ currentMovie }) {
  const title = currentMovie?.title || "DUNE : PART TWO";
  const backdrop = currentMovie?.backdrop_path 
    ? `https://image.tmdb.org/t/p/original${currentMovie.backdrop_path}` 
    : 'https://image.tmdb.org/t/p/original/xOMo8DxID7PBBtT0q1hXo8sN7uG.jpg';

  return (
    <div className="relative w-full h-[440px] bg-[#0b090e] flex flex-col items-center justify-center text-center px-4 overflow-hidden">
      {/* 배경 이미지 및 그라데이션 오버레이 */}
      <div className="absolute inset-0 opacity-30 bg-cover bg-center transition-all duration-700" style={{ backgroundImage: `url('${backdrop}')` }} />
      <div className="absolute inset-0 bg-gradient-to-b from-[#0b090e]/60 via-transparent to-[#0b090e] z-10" />
      
      <div className="relative z-20 max-w-2xl mt-4">
        <span className="text-xs uppercase tracking-widest text-purple-400 font-bold">거대한 서사, 압도적 장엄함</span>
        <h2 className="text-3xl md:text-5xl font-black text-white mt-2 mb-6 tracking-wider drop-shadow-lg">{title}</h2>
        <div className="flex justify-center gap-3">
          <button className="bg-[#503396] hover:bg-[#3b2570] text-white text-xs font-bold px-6 py-2.5 rounded-full shadow-lg transition">
            영화 상세 보기
          </button>
          <button className="bg-white/10 hover:bg-white/20 text-white text-xs font-bold px-6 py-2.5 rounded-full backdrop-blur-md transition border border-white/10">
            빠른 예매
          </button>
        </div>
      </div>
    </div>
  );
}

export default HeroSection;
